pid_t pid = fork();

if (pid < 0) {
    // Handle error
    perror("fork failed");
} else if (pid == 0) {
    // Child process context
    printf("I am the child: PID %d\n", getpid());
    // Use exec() to run a new program
} else {
    // Parent process context
    wait(NULL); // Wait for child to finish
    printf("I am the parent: PID %d\n", getpid());
}
